SQL_SUBS = ["Data Query Language (DQL)", "Data Definition Language (DDL)", "Data Control Language (DCL)",
            "Data Manipulation Language (DML)", "Transaction Control Language (TCL)"]

def sub(correct):
    """Distractors for SQL sub-language items: the other four minus one."""
    others = [s for s in SQL_SUBS if s != correct]
    return others[:3]

